__NUXT_JSONP__("/th/how-to-apply/student-visa-f1/overseas-students", (function(a){return {data:[{details:{slug:"th",pageTitle:"นักเรียนต่างชาติ | Mentor Language Institute",pageDescription:a,title:"นักเรียนต่างชาติ",image:"\u002Fimages\u002Fhow-to-apply\u002Foverseas-student\u002Foverseas-student.png",subtitle:[a,"หรือ","มี VISA STUDENT แล้วและจะเข้าประเทศสหรัฐอเมริกาอีกครั้ง"],category:[{title:"ขั้นตอนการสมัคร",image:"\u002Fimages\u002Fhow-to-apply\u002Foverseas-student\u002Fapplication-steps-th.png",listType:"decimal",lists:["สมัครกับ MLI (กรอกใบสมัครออนไลน์)","ส่งเอกสารที่ใช้ในการออก I-20","รับ I-20","ยื่นขอวีซ่านักเรียนและสัมภาษณ์วีซ่าที่สถานทูตสหรัฐฯ","รับวีซ่านักเรียน","เดินทางมายังประเทศสหรัฐอเมริกา"],description:["นักเรียนควรดำเนินการ อย่างน้อย 2 เดือน ก่อนวันเริ่มต้นหลักสูตรที่ต้องการ. เราจะแนะนำขั้นตอนการสมัครหลังจากที่คุณส่งใบสมัครออนไลน์กับ MLI."],hasApplyNow:true},{title:"นโยบายการยกเลิก",description:["ค่าธรรมเนียมการลงทะเบียน $150 จะถูกเรียกเก็บตอนสมัคร. ค่าธรรมเนียมการลงทะเบียนไม่สามารถคืนเงินได้ หากไม่ได้รับการอนุมัติวีซ่าหรือการลงทะเบียนถูกยกเลิก."]},{title:"หลังจากส่งใบสมัคร",image:"\u002Fimages\u002Fhow-to-apply\u002Foverseas-student\u002Fapplication-form-en.jpg",description:["หลังจากนักเรียนส่งใบสมัครออนไลน์ MLI จะดำเนินการและส่งลิงก์สำหรับ iMLI (หน้าสมัครออนไลน์ของนักเรียนแต่ละคน).\u003Cbr \u002F\u003Eนักเรียนสามารถทำตามขั้นตอนการสมัครที่ระบุไว้ใน iMLI."]}],applyOnline:{title:"สมัครเรียนออนไลน์",description:["กรอกข้อมูลในใบสมัครออนไลน์.\u003Cbr \u002F\u003Eติดต่อเราทาง e-mail หากมีคำถามใด ๆ","สมัครกับ MLI ผ่านการสมัครออนไลน์."],imageLink:{image:"\u002Fimages\u002Fhow-to-apply\u002Foverseas-student\u002Fapply-now-th.png",link:"\u002Fth\u002Fadmission"}},dir:"\u002Foverseas-students",path:"\u002Foverseas-students\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:30.080Z",updatedAt:"2025-05-26T12:06:27.839Z"}}],fetch:{},mutations:void 0}}("นักเรียนต่างชาติคือผู้ที่อาศัยอยู่นอกประเทศสหรัฐฯและจะสมัครวีซ่านักเรียน")));